CREATE TABLE `ap_report_options` (
  `id` int(11) NOT NULL,
  `client_id` int(11) NOT NULL,
  `period_id` int(11) NOT NULL,
  `report_title` varchar(255) DEFAULT 'Annual Report and Financial Statements',
  `cover_style` varchar(50) DEFAULT 'ModernPurple',
  `include_cover_page` tinyint(1) DEFAULT 1,
  `include_table_of_contents` tinyint(1) DEFAULT 1,
  `include_company_information` tinyint(1) DEFAULT 1,
  `include_accountants_report` tinyint(1) DEFAULT 1,
  `include_directors_report` tinyint(1) DEFAULT 1,
  `include_detailed_profit_and_loss` tinyint(1) DEFAULT 0,
  `watermark_text` varchar(50) DEFAULT '',
  `page_numbering` tinyint(1) DEFAULT 1,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `company_contacts` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`company_contacts`)),
  `custom_headings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`custom_headings`)),
  `revised_accounts` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`revised_accounts`)),
  `data_security` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`data_security`)),
  `auto_rounding_enabled` tinyint(1) DEFAULT 0,
  `rounding_account_pl` varchar(50) DEFAULT '7999',
  `rounding_account_bs` varchar(50) DEFAULT '3200',
  `entity_type` varchar(50) DEFAULT 'LimitedByShares'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

