INSERT INTO `cms_hero_slides` (`id`, `badge_text`, `title`, `highlight_word`, `subtitle`, `primary_cta_text`, `primary_cta_url`, `secondary_cta_text`, `secondary_cta_url`, `preview_image_url`, `rating_score`, `rating_count`, `sort_order`, `is_active`, `created_at`) VALUES
(1, 'HMRC & Companies House Recognized', 'The Unified Cloud Operating System for Modern UK Accounting Practices', 'Unified Cloud Operating System', 'Say goodbye to fragmented desktop tools and clunky data bridges. SanSuite unifies Practice Management, FRS 102/105 Accounts Production, CT600 Corporation Tax, SA100, MTD VAT, RTI Payroll, CoSec, and Unlimited eSign into a single, high-speed cloud platform.', 'Book a 1-on-1 Practice Demo', '/book-demo', 'Explore All 10 Modules', '#modules', NULL, 4.9, 1420, 1, 1, '2026-09-27 09:36:59');

