(1, 'SanSuite', 'The Unified Cloud Operating System for UK Accounting Practices', NULL, 'contact@sansuite.co.uk', '+44 (0) 20 8000 0000', '1 Canada Square, Canary Wharf, London, E14 5AA, United Kingdom', '12345678', 'GB 987 6543 21', 'HMRC Making Tax Digital for Income Tax (MTD IT) Live & Fully Compliant', '/solutions/mtd-it', 1, NULL, 'SanSuite - UK Cloud Accounting & Practice Management Software', 'All-in-one UK accounting, tax, bookkeeping, and practice management software suite for accountants and bookkeepers. HMRC and Companies House compliant.', '2026-09-27 10:17:10', '{\"visibility\":{\"homeHero\":true,\"homeTrustBar\":true,\"homeModules\":true,\"homeRoi\":true,\"homeTestimonials\":true,\"homeCta\":true,\"pricingTiers\":true,\"pricingComparison\":true,\"pricingFaqs\":true,\"bookDemoBenefits\":true,\"contactMap\":true,\"contactHotlines\":true},\"trustBar\":{\"eyebrow\":\"Enterprise Security & UK Statutory Compliance\",\"heading\":\"Trusted by UK Chartered Accountants, CPAs, and Independent Accounting Practices\",\"badges\":[{\"title\":\"HMRC Recognized\",\"subtitle\":\"MTD VAT, MTD IT, CT600 & RTI\",\"badge\":\"Direct Digital Gateway\"},{\"title\":\"Companies House\",\"subtitle\":\"Direct electronic iXBRL filings\",\"badge\":\"One-Click Submission\"},{\"title\":\"ICAEW & ACCA Standard\",\"subtitle\":\"FRS 102 (1A) & FRS 105 compliant\",\"badge\":\"Statutory Taxonomies\"},{\"title\":\"Bank-Grade Encryption\",\"subtitle\":\"AES-256 data security at rest\",\"badge\":\"UK Data Residency\"},{\"title\":\"99.99% Cloud Uptime\",\"subtitle\":\"ISO 27001 certified data centers\",\"badge\":\"Auto-Failover SLA\"}]},\"roiCalculator\":{\"eyebrow\":\"Interactive Practice Efficiency Calculator\",\"heading\":\"See How Much Time & Cost SanSuite Saves Your Firm\",\"subtitle\":\"Unlike legacy software providers who charge exorbitant per-seat license fees, SanSuite includes unlimited staff users and unified data flow across all compliance workflows.\",\"defaultClients\":100,\"defaultTeam\":4,\"hoursPerClientMultiplier\":3.6,\"legacySeatCost\":65,\"legacyClientCost\":2.2},\"pricingMatrix\":[{\"feature\":\"Unlimited Staff Users & Interns\",\"starter\":true,\"growth\":true,\"enterprise\":true},{\"feature\":\"Practice Management & CRM\",\"starter\":true,\"growth\":true,\"enterprise\":true},{\"feature\":\"AML & Risk Assessment Verification\",\"starter\":true,\"growth\":true,\"enterprise\":true},{\"feature\":\"Accounts Production (FRS 102 1A / 105)\",\"starter\":true,\"growth\":true,\"enterprise\":true},{\"feature\":\"Corporation Tax (CT600) Direct Filing\",\"starter\":true,\"growth\":true,\"enterprise\":true},{\"feature\":\"Bookkeeping & MTD for VAT Gateway\",\"starter\":true,\"growth\":true,\"enterprise\":true},{\"feature\":\"Unlimited SanSuite eSignatures (eIDAS)\",\"starter\":true,\"growth\":true,\"enterprise\":true},{\"feature\":\"Self Assessment (SA100, SA800, SA900)\",\"starter\":false,\"growth\":true,\"enterprise\":true},{\"feature\":\"Payroll & RTI Auto-Enrolment Pensions\",\"starter\":false,\"growth\":true,\"enterprise\":true},{\"feature\":\"Company Secretarial & Formations\",\"starter\":false,\"growth\":true,\"enterprise\":true},{\"feature\":\"Making Tax Digital for Income Tax (MTD IT)\",\"starter\":false,\"growth\":true,\"enterprise\":true},{\"feature\":\"Client Portal 365 SME Mobile Hub\",\"starter\":false,\"growth\":true,\"enterprise\":true},{\"feature\":\"Priority UK Phone & Remote Desktop Support\",\"starter\":false,\"growth\":true,\"enterprise\":true},{\"feature\":\"Full White-Label & Custom Subdomain\",\"starter\":false,\"growth\":false,\"enterprise\":true},{\"feature\":\"Dedicated UK Customer Success Manager\",\"starter\":false,\"growth\":false,\"enterprise\":true}],\"bookDemo\":{\"heading\":\"Experience the Power of Unified Practice Cloud\",\"subtitle\":\"Book a customized 1-on-1 walkthrough with a UK accounting technology specialist.\",\"guarantee\":\"No obligation. No credit card required. 30-minute tailored walkthrough.\",\"benefits\":[{\"title\":\"Tailored to Your Practice Size\",\"description\":\"Whether you manage 20 or 2,000 clients, see workflows tuned to your exact operational scale.\"},{\"title\":\"Live Direct Filing Gateway Demos\",\"description\":\"Watch real-time live submission simulations for HMRC (VAT, CT600, RTI) and Companies House.\"},{\"title\":\"Free Zero-Downtime Data Migration\",\"description\":\"Learn how our UK team transfers client records, balances, and contacts from your legacy software.\"},{\"title\":\"Zero Lock-In & Unlimited Staff\",\"description\":\"Get transparent quote with unlimited users, unlimited eSign, and no per-seat penalty fees.\"}],\"brackets\":[\"1 - 20 Clients\",\"20 - 50 Clients\",\"50 - 150 Clients\",\"150 - 500 Clients\",\"500+ Clients\"]},\"contactInfo\":{\"officeName\":\"London Headquarters\",\"address\":\"1 Canada Square, Canary Wharf, London, E14 5AA, United Kingdom\",\"companyReg\":\"Registered in England & Wales No. 12345678\",\"vatReg\":\"VAT Registration No. GB 987 6543 21\",\"supportPhone\":\"+44 (0) 20 8000 0000\",\"salesPhone\":\"+44 (0) 20 8000 0001\",\"weekdayHours\":\"Monday - Friday: 08:30 - 18:00 GMT\",\"saturdayHours\":\"Saturday (Filing Deadline Months): 09:00 - 14:00 GMT\",\"generalEmail\":\"contact@sansuite.co.uk\",\"salesEmail\":\"sales@sansuite.co.uk\",\"supportEmail\":\"support@sansuite.co.uk\",\"complianceEmail\":\"compliance@sansuite.co.uk\"},\"homeCta\":{\"heading\":\"Ready to modernise your accountancy practice?\",\"subtitle\":\"Join hundreds of UK firms eliminating disconnected software silos with SanSuite unified cloud suite.\",\"buttonText\":\"Book a 1-on-1 Practice Demo\",\"buttonUrl\":\"/book-demo\"}}');

