--
-- Table structure for table `credit_notes`
--

CREATE TABLE `credit_notes` (
  `id` int(11) NOT NULL,
  `client_id` int(11) NOT NULL,
  `contact_id` int(11) DEFAULT NULL,
  `type` varchar(20) NOT NULL DEFAULT 'Sales',
  `credit_note_number` varchar(50) NOT NULL,
  `credit_note_date` date NOT NULL,
  `sub_total` decimal(15,2) DEFAULT 0.00,
  `vat_total` decimal(15,2) DEFAULT 0.00,
  `total_amount` decimal(15,2) DEFAULT 0.00,
  `allocated_amount` decimal(15,2) DEFAULT 0.00,
  `remaining_amount` decimal(15,2) DEFAULT 0.00,
  `status` varchar(30) DEFAULT 'Issued',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `credit_note_allocations`
--

CREATE TABLE `credit_note_allocations` (
  `id` int(11) NOT NULL,
  `credit_note_id` int(11) NOT NULL,
  `invoice_id` int(11) DEFAULT NULL,
  `purchase_id` int(11) DEFAULT NULL,
  `amount` decimal(15,2) NOT NULL,
  `allocated_date` date NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `credit_note_items`
--

CREATE TABLE `credit_note_items` (
  `id` int(11) NOT NULL,
  `credit_note_id` int(11) NOT NULL,
  `description` text DEFAULT NULL,
  `quantity` decimal(12,2) DEFAULT 1.00,
  `unit_price` decimal(15,2) DEFAULT 0.00,
  `net_amount` decimal(15,2) DEFAULT 0.00,
  `vat_rate` decimal(5,2) DEFAULT 20.00,
  `vat_amount` decimal(15,2) DEFAULT 0.00,
  `nominal_code` varchar(20) DEFAULT '4000'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `cs_filings`
--

CREATE TABLE `cs_filings` (
  `id` int(11) NOT NULL,
  `client_id` int(11) NOT NULL,
  `form_type` varchar(50) NOT NULL,
  `status` varchar(50) DEFAULT 'Draft',
  `submission_date` timestamp NOT NULL DEFAULT current_timestamp(),
  `transaction_id` varchar(100) DEFAULT NULL,
  `submission_number` varchar(100) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `payload_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`payload_json`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

