--
-- Table structure for table `esign_documents`
--

CREATE TABLE `esign_documents` (
  `id` int(11) NOT NULL,
  `practice_id` int(11) DEFAULT NULL,
  `client_id` int(11) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `file_path` varchar(255) DEFAULT NULL,
  `signed_file_path` varchar(255) DEFAULT NULL,
  `file_size` int(11) DEFAULT NULL,
  `source_module` varchar(100) DEFAULT NULL,
  `message` text DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Draft',
  `created_by_user_id` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `completed_at` timestamp NULL DEFAULT NULL,
  `expiry_date` timestamp NULL DEFAULT NULL,
  `is_password_protected` tinyint(1) DEFAULT 0,
  `access_code` varchar(100) DEFAULT NULL,
  `attachments_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`attachments_json`)),
  `email_subject` varchar(255) DEFAULT NULL,
  `email_template_id` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

