--
-- Table structure for table `pm_aml_checks`
--

CREATE TABLE `pm_aml_checks` (
  `id` int(11) NOT NULL,
  `practice_id` int(11) NOT NULL,
  `client_id` int(11) NOT NULL,
  `risk_level` varchar(20) DEFAULT 'Low',
  `id_verification_status` varchar(50) DEFAULT 'Verified',
  `address_verification_status` varchar(50) DEFAULT 'Verified',
  `pep_sanctions_checked` tinyint(1) DEFAULT 1,
  `id_document_type` varchar(100) DEFAULT 'Passport',
  `id_document_number` varchar(100) DEFAULT NULL,
  `id_expiry_date` date DEFAULT NULL,
  `risk_notes` text DEFAULT NULL,
  `verified_by` int(11) DEFAULT NULL,
  `verified_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `next_review_date` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

