  `direction` varchar(20) NOT NULL DEFAULT 'Inbound',
  `thread_id` varchar(255) DEFAULT NULL,
  `has_attachments` tinyint(1) DEFAULT 0,
  `attachments_json` text DEFAULT NULL,
