--
-- Table structure for table `pm_deadlines`
--

CREATE TABLE `pm_deadlines` (
  `id` int(11) NOT NULL,
  `practice_id` int(11) NOT NULL,
  `client_id` int(11) NOT NULL,
  `service_id` int(11) DEFAULT NULL,
  `period_id` int(11) DEFAULT NULL,
  `deadline_name` varchar(255) NOT NULL,
  `service_type` varchar(50) NOT NULL,
  `statutory_deadline_date` date NOT NULL,
  `internal_deadline_date` date DEFAULT NULL,
  `status` varchar(30) DEFAULT 'Upcoming',
  `assigned_user_id` int(11) DEFAULT NULL,
  `submission_ref` varchar(150) DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `submitted_by` int(11) DEFAULT NULL,
  `is_statutory` tinyint(1) DEFAULT 1,
  `reminder_days` varchar(100) DEFAULT '30,14,7,1',
  `last_reminder_sent_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

