(1, 1, 'DEADLINE_REMINDER_30D', 'Filing Deadline Reminder (30 Days Notice)', 'DeadlineReminder', 'Upcoming Filing Deadline Reminder: {{service_name}} for {{client_name}}', '<p>Dear {{contact_name}},</p><p>This is a courtesy reminder that the <strong>{{service_name}}</strong> filing for <strong>{{client_name}}</strong> is due on <strong>{{deadline_date}}</strong>.</p><p>Please ensure all supporting records and documents have been uploaded to our secure client portal to avoid any late filing penalties from HMRC / Companies House.</p><p>Best regards,<br>{{firm_name}} Compliance Team</p>', 'Filing deadline reminder for {{service_name}} on {{deadline_date}}.', '[\"{{client_name}}\",\"{{contact_name}}\",\"{{service_name}}\",\"{{deadline_date}}\",\"{{company_number}}\",\"{{firm_name}}\"]', 1, '2026-09-05 04:38:06'),
(2, 1, 'DOC_REQUEST_CHASER', 'Document Request & Missing Information', 'DocumentRequest', 'Action Required: Outstanding Documents for {{client_name}}', '<p>Dear {{contact_name}},</p><p>We are currently preparing your accounts and tax computations. We require the following outstanding items to proceed:</p><p>{{requested_items}}</p><p>You can securely upload your files using this link: <a href=\"{{upload_link}}\">{{upload_link}}</a></p><p>Thank you for your prompt cooperation.</p><p>Best regards,<br>{{firm_name}}</p>', 'Please upload your requested documents using the link {{upload_link}}.', '[\"{{client_name}}\",\"{{contact_name}}\",\"{{requested_items}}\",\"{{upload_link}}\",\"{{firm_name}}\"]', 1, '2026-09-05 04:38:06'),
(3, 1, 'LOE_PROPOSAL_DISPATCH', 'Letter of Engagement & Fee Proposal', 'Proposal', 'Your Letter of Engagement & Fee Schedule from {{firm_name}}', '<p>Dear {{contact_name}},</p><p>Thank you for choosing <strong>{{firm_name}}</strong> as your professional accountants and tax advisors.</p><p>Please review and electronically sign your Letter of Engagement by clicking the link below:</p><p><a href=\"{{sign_link}}\" style=\"background:#6c5ce7;color:#fff;padding:10px 20px;text-decoration:none;border-radius:4px;\">Review & E-Sign Document</a></p><p>Agreed Annual/Monthly Fee: <strong>{{agreed_fee}}</strong></p><p>Best regards,<br>{{firm_name}}</p>', 'Please review and sign your Letter of Engagement: {{sign_link}}', '[\"{{client_name}}\",\"{{contact_name}}\",\"{{agreed_fee}}\",\"{{sign_link}}\",\"{{firm_name}}\"]', 1, '2026-09-05 04:38:06'),
(4, 1, 'GENERAL_ANNOUNCEMENT', 'Client Newsletter & Tax Update Announcement', 'BulkAnnouncement', 'Important Tax & Regulatory Update from {{firm_name}}', '<p>Dear Valued Client,</p><p>We are pleased to share our latest regulatory newsletter covering key updates in UK tax legislation, Making Tax Digital (MTD), and compliance guidelines.</p><p>Please feel free to reach out to your designated account manager if you have any questions.</p><p>Warm regards,<br>{{firm_name}}</p>', 'Important Tax update from {{firm_name}}', '[\"{{client_name}}\",\"{{contact_name}}\",\"{{firm_name}}\",\"{{manager_name}}\"]', 1, '2026-09-05 04:38:06');

