INSERT INTO `pm_loe_templates` (`id`, `practice_id`, `template_name`, `template_type`, `header_html`, `body_html`, `footer_html`, `logo_url`, `is_default`, `created_at`) VALUES
(1, 1, 'Standard Standard Letter of Engagement (UK Practice)', 'LetterOfEngagement', '<div style=\"text-align:center;padding:20px;border-bottom:2px solid #6c5ce7;\"><h2>LETTER OF ENGAGEMENT & PROFESSIONAL TERMS</h2><p>SanSuite Chartered Accountants & Registered Auditors</p></div>', '<h3>1. Purpose & Scope of Engagement</h3>\n<p>This Letter of Engagement sets out the basis on which we are to act as your accountants and tax advisors for <strong>{{client_name}}</strong> (Company No: {{company_number}}).</p>\n\n<h3>2. Contracted Professional Services</h3>\n<p>We agree to provide the following compliance and advisory services:</p>\n<div style=\"background:#f8fafc;padding:15px;border-radius:6px;margin:15px 0;\">\n{{services_list}}\n</div>\n\n<h3>3. Agreed Professional Fees</h3>\n<p>Our agreed professional fee for the contracted services is <strong>{{agreed_fee}}</strong>, payable in accordance with our standard payment terms.</p>\n\n<h3>4. Client Responsibilities & Data Protection</h3>\n<p>You agree to provide full, complete, and accurate records in a timely manner. We will process all personal data strictly in compliance with UK GDPR and Data Protection Act 2018 regulations.</p>\n\n<h3>5. Agreement & Electronic Signature</h3>\n<p>By signing below, you confirm your acceptance of the terms and conditions outlined in this agreement.</p>', '<div style=\"text-align:center;font-size:12px;color:#64748b;margin-top:30px;border-top:1px solid #e2e8f0;padding-top:10px;\"><p>SanSuite Practice Management System - Legally Binding Electronic Document</p></div>', NULL, 1, '2026-09-01 09:09:01');

