INSERT INTO `practice_document_templates` (`id`, `practice_id`, `title`, `type`, `version`, `content`, `created_at`, `file_name`, `template_type`, `doc_type`, `email_subject`, `email_body`) VALUES
(4, 1, 'Proposal', '', '2026.1', 'Dear [ContactFirstName] [ContactLastName],\n\nPROPOSAL FOR PROFESSIONAL SERVICES\n\nWe are pleased to present our proposal to provide accountancy, taxation, and statutory advisory services to [CompanyName].\n\n1. Scope of Proposed Services\n[ServiceDetails]\n\n2. Fee Structure & Investment Summary\n[ProposalPriceSummary]\n\nWe look forward to working with you.\n\nYours sincerely,\n[ServiceManager]\n[PracticeName]', '2026-09-01 06:57:14', 'Proposal', 'Proposal Letter', 'Default', 'Proposal for Accountancy Services - [CompanyName]', 'Dear [ContactFirstName],\n\nPlease find attached our formal proposal for accountancy services for [CompanyName].\n\nBest regards,\n[PracticeName]'),
(5, 1, 'LETTER OF ENGAGEMENT', '', '2026.1', 'Dear [ContactFirstName] [ContactLastName],\n\nLETTER OF ENGAGEMENT - STATUTORY COMPLIANCE & ADVISORY\n\nDate: [BusinessStartDate]\nClient: [CompanyName] (Registration No: [RegistrationNo])\n\n1. Purpose & Scope of Engagement\nThis letter sets out the basis on which [PracticeName] is to act as your accountants and tax advisors.\n\n2. Agreed Schedule of Services\n[ServiceDetails]\n\n3. Professional Fees\n[ServicePriceDetails]\n\nPlease sign and return this letter via Capisign.\n\nYours sincerely,\n[ServiceManager]\n[PracticeName]', '2026-09-01 06:57:14', 'LETTER OF ENGAGEMENT', 'Letter of Engagement', 'Default', 'Letter of Engagement for [CompanyName] - Please Sign via Capisign', 'Dear [ContactFirstName],\n\nPlease review and sign the attached Letter of Engagement for [CompanyName].\n\nKind regards,\n[PracticeName]'),
(6, 1, 'Disengagement Letter for Limited', '', '2026.1', 'Dear Directors,\n\nDISENGAGEMENT OF PROFESSIONAL SERVICES - LIMITED COMPANY\n\nFollowing our decision that we will no longer act in connection with the taxation and statutory accounting affairs of [CompanyName] (Company No: [RegistrationNo]), we are writing to confirm our understanding of remaining responsibilities.\n\n1. The last statutory accounts submitted to Companies House was for the period ending [BookStartDate].\n2. The last tax return submitted to HM Revenue & Customs was for the accounting period ended [BookStartDate].\n3. You will be responsible for the agreement of all future assessments arising after the date of this letter.\n\nYours sincerely,\n[ServiceManager]\n[PracticeName]', '2026-09-01 06:57:14', 'Disengagement Letter for Limited', 'Disengagement Letter for Limited', 'Default', 'Disengagement Notice - [CompanyName]', 'Dear Directors,\n\nPlease find attached the formal disengagement letter regarding [CompanyName].\n\nRegards,\n[PracticeName]'),
(7, 1, 'Disengagement Letter for Individual', '', '2026.1', 'Dear [ContactFirstName] [ContactLastName],\n\nDISENGAGEMENT OF SERVICES - INDIVIDUAL / SOLE TRADER\n\nFollowing our decision that we should no longer act in connection with your personal taxation affairs (UTR: [UTRNo]), we are writing to confirm our understanding of our remaining responsibilities.\n\n1. The last tax return that was submitted to the HM Revenue & Customs was the return for the tax year ended [BookStartDate].\n2. You will be responsible for the agreement of all assessments arising from the last tax return submitted.\n3. We are today writing to HM Revenue & Customs to advise that we are no longer acting for you.\n\nYours sincerely,\n[ServiceManager]\n[PracticeName]', '2026-09-01 06:57:14', 'Disengagement Letter for Individual', 'Disengagement Letter for Individual', 'Default', 'Disengagement of Tax Services - [ContactFirstName] [ContactLastName]', 'Dear [ContactFirstName],\n\nPlease find attached your formal disengagement letter.\n\nBest regards,\n[PracticeName]'),
(8, 1, 'CUSTOM DIS LETTER', '', '2026.1', 'Dear Board of Directors,\n\nCONFIRMATION OF TERMINATION OF ENGAGEMENT\n\nClient: [CompanyName]\nPractice: [PracticeName]\n\nThis letter confirms that our engagement in respect of [CompanyName] has ceased effective immediately.\n\nYours faithfully,\n[ServiceManager]', '2026-09-01 06:57:14', 'CUSTOM DIS LETTER', 'Disengagement Letter for Limited', 'Custom', 'Notice of Termination - [CompanyName]', 'Dear Directors,\n\nPlease see attached confirmation letter.');

