(1, 1, 'Classic Corporate (Standard UK)', 'PDF', '#6c5ce7', NULL, 'INVOICE / STATUTORY FEE NOTE', 'Thank you for your business. Please settle this fee note within 30 days of invoice date.', 'Payment Terms: Net 30 Days. Late payments subject to statutory interest under Late Payment of Commercial Debts Act 1998.', 'Barclays Bank UK PLC', 'Pegasus Accountancy Services Ltd - Client Account', '20-00-00', '88776655', 'GB29BARC20000088776655', 'BARCGB22', 'Please quote Invoice Number [invoice.number] as reference when making BACS payment.', 0, '2026-09-01 05:57:39', 'A4', 'Invoice', 'Draft Invoice', 'Credit Note', 'Invoice', 25, 25, 25, 25, 40, 1, 1),
(2, 1, 'Modern Minimalist (Sleek Purple)', 'PDF', '#4f46e5', NULL, 'PROFESSIONAL SERVICES INVOICE', 'Pegasus Accountancy Services Ltd • Registered in England & Wales #12345678', 'Due upon receipt via BACS or Direct Debit.', 'HSBC UK Bank PLC', 'Pegasus Accountancy Services Ltd', '40-02-00', '11223344', 'GB12MIDL40020011223344', 'MIDLGB22', 'Electronic BACS / Faster Payments Reference: [invoice.number]', 0, '2026-09-01 05:57:39', 'A4', 'Invoice', 'Draft Invoice', 'Credit Note', 'Invoice', 25, 25, 25, 25, 40, 1, 1),
